import { useEffect, useState } from 'react';
import FooterNav from '../../components/dashboard/FooterNav';
import Navbar from '../../components/dashboard/Navbar';
import SaldoComponent from '../../components/dashboard/Saldo';

import axios from  'axios';
import jwtDecode from 'jwt-decode';
import { Link, useNavigate } from "react-router-dom";
import PesanComponent from '../../components/dashboard/Pesan';

const verifyToken = (serviceToken) => {
    if (!serviceToken) {
        return false;
    }
    const decoded = jwtDecode(serviceToken);
    /**
     * Property 'exp' does not exist on type '<T = unknown>(token: string, options?: JwtDecodeOptions | undefined) => T'.
     */
    return decoded.exp > Date.now() / 1000;
};

const Pesan = () => {

    const navigate = useNavigate();
    const [token, setToken] = useState(
        JSON.parse(localStorage.getItem('token')) !== null ? 
            JSON.parse(localStorage.getItem('token')).token :
            null
    );
    const [cartState, setCartState] = useState([]);
    const [pesanData, setPesanData] = useState([]);

    const [page, setPage] = useState({ value: 1 });
    const [pageInfo, setPageInfo] = useState(null);
    const [pageSize, setPageSize] = useState({ value: 24 });

    useEffect(() => {

        const getCart = async () => {
            try {
              const cartData = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/cart/list`, {
                headers: {
                  Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                }
              });
              setCartState(cartData.data.result);
            } catch (err) {
              console.log(err);
            }
        };
        const getPesan = async () => {
            try {
                const getData = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/pesan`, {
                    headers: {
                    Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                    }
                });
                let no = 0;

                setPesanData(getData.data.result.data.map((v) => ({...v, no: no+=1})));

                const pageInfoRes = Object.keys(getData.data.result)
                    .filter((key) => {
                        if (key !== 'data') return true;
                        return false;
                    })
                    .reduce((cur, key) => Object.assign(cur, { [key]: getData.data.result[key] }), {});

                setPageInfo(pageInfoRes);

            } catch (err) {
              console.log(err);
            }
        };

        getCart();
        getPesan();

        if(!verifyToken(token)){
            localStorage.removeItem('token');
            navigate('/');
        }

    }, []);

    return (
        <div>
            <Navbar cartState={cartState} UpdatedCartState={setCartState} />
            <PesanComponent
                pesanData={pesanData}
                updatedData={setPesanData}
                page={page}
                updatedPage={setPage}
                pageInfo={pageInfo}
                updatedPageInfo={setPageInfo}
                pageSize={pageSize}
                updatedPageSize={setPageSize}
            />
            <FooterNav />
        </div>
    )
}

export default Pesan
