import { useEffect, useState } from 'react';
import FooterNav from '../../components/dashboard/FooterNav';
import Navbar from '../../components/dashboard/Navbar';
import Slider from '../../components/Slider';
import Main from '../../components/dashboard/Main';
import DropshipComponent from '../../components/dashboard/Dropship';

import axios from  'axios';
import jwtDecode from 'jwt-decode';
import { Link, useNavigate, useSearchParams } from "react-router-dom";

const verifyToken = (serviceToken) => {
    if (!serviceToken) {
        return false;
    }
    const decoded = jwtDecode(serviceToken);
    /**
     * Property 'exp' does not exist on type '<T = unknown>(token: string, options?: JwtDecodeOptions | undefined) => T'.
     */
    return decoded.exp > Date.now() / 1000;
};

const Dropship = () => {

    const navigate = useNavigate();
    const [token, setToken] = useState(
        JSON.parse(localStorage.getItem('token')) !== null ? 
            JSON.parse(localStorage.getItem('token')).token :
            null
    );
    const [cartState, setCartState] = useState([]);
    let [searchParams, setSearchParams] = useSearchParams();
    const [data, setData] = useState([]);
    const [dataPo, setDataPo] = useState({});

    useEffect(() => {
        const getCart = async () => {
            try {
              const cartData = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/cart/list`, {
                headers: {
                  Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                }
              });
              setCartState(cartData.data.result);
            } catch (err) {
              console.log(err);
            }
        };
        const getData = async () => {
            try {
                const po = await axios.get(
                  `${process.env.REACT_APP_API_URL}/api/dashboard/dropship/list`, {
                    params: {
                        invoice: searchParams.get('invoice'),
                        idpoproduk: searchParams.get('idpoproduk')
                    },
                    headers: {
                        Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                    }
                  }
                );
                let no = 0;
                setData(po.data.result.map((v) => ({ ...v, no: no += 1 })));

            } catch (err) {
                console.log(err);
            }
        }
        const getDataPo = async () => {
            try {
                const po = await axios.get(
                  `${process.env.REACT_APP_API_URL}/api/dashboard/preorder/opened/${searchParams.get('idpoproduk')}`, {
                    headers: {
                        Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                    }
                  }
                );
                setDataPo(po.data.result);

            } catch (err) {
                console.log(err);
            }
        }
        getCart();
        getData();
        getDataPo();

        if(!verifyToken(token)){
            localStorage.removeItem('token');
            navigate('/');
        }
    }, []);

    return (
        <div>
            <Navbar cartState={cartState} UpdatedCartState={setCartState} />
            <DropshipComponent data={data} dataPo={dataPo} updatedData={setData} />
            <FooterNav />   
        </div>
    )
}

export default Dropship
