import { useState, useEffect, forwardRef } from 'react';
import PropTypes from 'prop-types';
import styledComponents from "styled-components";

import {
  Box,
  Divider,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Fab,
  Grid,
  Typography,
  TextField,
  Button,
  Menu,
  MenuItem,
  ListItemIcon,
  Modal,
  InputBase,
  InputLabel,
  IconButton,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Pagination,
  Select,
  Stack,
  Snackbar,
  Paper
} from "@mui/material";
import MuiAlert from '@mui/material/Alert';

import axios from  "axios";
import { Formik } from 'formik';

import AddCircleIcon from '@mui/icons-material/AddCircle';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

const modalStyle = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: { xs: '80%', md: 400 },
    maxHeight: '66vh',
    bgcolor: 'background.paper',
    boxShadow: 24,
    p: 4,
    overflow: 'scroll'
};
  
const Container = styledComponents.div`
    padding: 20px;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
`;
  
const Alert = forwardRef(function Alert(props, ref) {
    return <MuiAlert elevation={6} ref={ref} variant="filled" {...props} />;
});

const Rekeningku = () => {
    const [token, setToken] = useState(
        JSON.parse(localStorage.getItem('token')) !== null ? 
            JSON.parse(localStorage.getItem('token')).token :
            null
    );
    const [openAlert, setOpenAlert] = useState(false);
    const [data, setData] = useState([]);
    const [open, setOpen] = useState(false);
    const [openEdit, setOpenEdit] = useState(false);
    const [valToEdit, setValToEdit] = useState(null);
    const [openDelDialog, setOpenDelDialog] = useState(false);
    const [id, setId] = useState(null);

    const handleDeleteDialog = (id) => {
        setId(id);
        setOpenDelDialog(true);
    };
  
    const handleCloseDeleteDialog = () => {
        setId(null);
        setOpenDelDialog(false);
    };
    const handleOpen = () => setOpen(true);
    const handleClose = () => setOpen(false);
    const handleOpenEdit = (val) => {
        setValToEdit(val);
        setOpenEdit(true);
    };
    const handleCloseEdit = () => {
        setValToEdit(null);
        setOpenEdit(false);
    };
    const [alertStatus, setAlertStatus] = useState('success');
    const [alertMessage, setAlertMessage] = useState('');
    const handleCloseAlert = (event, reason) => {
        if (reason === 'clickaway') {
            return;
        }
        setOpenAlert(false);
    };

    const handleDelete = async (id) => {
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku/${id}`, {
            headers: {
                Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
            }
        });

        // update states
        const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku`, {
            headers: {
              Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
            }
        });
        let number = 0;
        setData(res.data.result.map((v) => {
            number+=1;
            return { ...v, no: number };
        }));
        
        handleCloseDeleteDialog();
    };

    useEffect(() => {
        
        const getData = async () => {
            try {
                const rekeningku = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku`, {
                    headers: {
                        Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                    }
                });
                let number = 0;
                setData(rekeningku.data.result.map((v) => {
                    number+=1;
                    return { ...v, no: number };
                }));
            } catch (err) {
                console.log(err);
            }
        };
        getData();
    }, [])

    return (
        <Container>
            <Snackbar
                open={openAlert}
                autoHideDuration={2500}
                onClose={handleCloseAlert}
                anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
                key={'top' + 'center'}
            >
                <Alert onClose={handleCloseAlert} severity={alertStatus} sx={{ width: '100%' }}>
                    {alertMessage}
                </Alert>
            </Snackbar>
            <Dialog
                open={openDelDialog}
                onClose={handleCloseDeleteDialog}
                aria-labelledby="alert-dialog-title"
                aria-describedby="alert-dialog-description"
            >
            <DialogContent>
                <DialogContentText id="alert-dialog-description">
                    Apakah anda akan menghapus data ?
                </DialogContentText>
                </DialogContent>
                <DialogActions>
                <Button onClick={handleCloseDeleteDialog}>Batal</Button>
                <Button onClick={() => handleDelete(id)}>
                    Ya
                </Button>
                </DialogActions>
            </Dialog>
            <Modal
                open={open}
                onClose={handleClose}
                aria-labelledby="modal-modal-title"
                aria-describedby="modal-modal-description"
            >
                <Box sx={modalStyle}>
                <Formik
                    initialValues={{ bank: null, namapemilik: null, rekening: null }}
                    validate={values => {
                        const errors = {};
                        if (!values.bank) {
                            errors.bank = 'Wajib diisi';
                        }
                        if (!values.namapemilik) {
                            errors.namapemilik = 'Wajib diisi';
                        }
                        if (!values.rekening) {
                            errors.rekening = 'Wajib diisi';
                        }
                        return errors;
                    }}
                    onSubmit={async (values, { setSubmitting }) => {
                        try {
                            await axios.post(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku`, values, {
                                headers: {
                                    Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                                }
                            });
                            // update states
                            const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku`, {
                                headers: {
                                  Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                                }
                            });
                            let number = 0;
                            setData(res.data.result.map((v) => {
                                number+=1;
                                return { ...v, no: number };
                            }));
                            setAlertStatus('success');
                            setAlertMessage('Tambah rekening berhasil');
                            setOpenAlert(true);
                            handleClose();
                        } catch (err) {
                            console.log(err);
                            setSubmitting(false);
                        }
                    }}
                >
                    {({
                    values,
                    errors,
                    touched,
                    handleChange,
                    handleBlur,
                    handleSubmit,
                    isSubmitting,
                    /* and other goodies */
                    }) => (
                    <form onSubmit={handleSubmit}>
                        <Grid container spacing={2}>
                            <Grid item xs={12} sx={{ textAlign: 'center' }}>
                                <Typography id="modal-modal-title" variant="subtitle1" fontWeight="700">
                                    Tambah Rekening
                                </Typography>
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    id="outlined-multiline-flexible"
                                    required
                                    fullWidth
                                    label="Nama Bank"
                                    onChange={handleChange}
                                    name="bank"
                                />
                                <Typography id="modal-modal-title" color="red" variant="subtitle2" component="span" sx={{ padding: '5px'}}>
                                    {errors.bank && touched.bank && errors.bank}
                                </Typography>
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    id="outlined-multiline-flexible"
                                    required
                                    fullWidth
                                    label="Nama Pemilik"
                                    onChange={handleChange}
                                    name="namapemilik"
                                />
                                <Typography id="modal-modal-title" color="red" variant="subtitle2" component="span" sx={{ padding: '5px'}}>
                                    {errors.namapemilik && touched.namapemilik && errors.namapemilik}
                                </Typography>
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    id="outlined-multiline-flexible"
                                    required
                                    fullWidth
                                    label="Nomor Rekening"
                                    onChange={handleChange}
                                    inputProps={{ inputMode: 'numeric', pattern: '[0-9]*', type: 'number' }}
                                    name="rekening"
                                />
                                <Typography id="modal-modal-title" color="red" variant="subtitle2" component="span" sx={{ padding: '5px'}}>
                                    {errors.rekening && touched.rekening && errors.rekening}
                                </Typography>
                            </Grid>
                            <Grid item xs={12} sx={{ textAlign: 'right', padding: '10px 0px' }}>
                                <Button variant="contained" type="submit" disabled={isSubmitting}>Submit</Button>
                            </Grid>
                        </Grid>
                    </form>
                    )}
                </Formik>
                </Box>
            </Modal>
            <Modal
                open={openEdit}
                onClose={handleCloseEdit}
                aria-labelledby="modal-modal-title"
                aria-describedby="modal-modal-description"
            >
                <Box sx={modalStyle}>
                    <Formik
                        initialValues={{ bank: null, namapemilik: null, rekening: null }}
                        validate={values => {
                            const errors = {};
                            return errors;
                        }}
                        onSubmit={async(values, { setSubmitting }) => {
                            const filteredVal = Object.keys(values).reduce((newObj, key) => {
                                const value = values[key];
                                if (value !== null) {
                                    newObj[key] = value;
                                }
                                return newObj;
                            }, {});
                            if (Object.keys(filteredVal).length === 0) {
                                setAlertStatus('warning');
                                setAlertMessage('Tidak ada perubahan')
                                setOpenAlert(true);
                                setSubmitting(false);
                            } else {
                                try {
                                    await axios.put(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku/${valToEdit.idrek}`, filteredVal, {
                                        headers: {
                                            Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                                        }
                                    });
                                    // update states
                                    const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/rekeningku`, {
                                        headers: {
                                        Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
                                        }
                                    });
                                    let number = 0;
                                    setData(res.data.result.map((v) => {
                                        number+=1;
                                        return { ...v, no: number };
                                    }));
                                    setAlertStatus('success');
                                    setAlertMessage('Ubah rekening berhasil');
                                    setOpenAlert(true);
                                    handleCloseEdit();
                                } catch (err) {
                                    console.log(err);
                                    setSubmitting(false);
                                }
                            }
                        }}
                    >
                        {({
                        values,
                        errors,
                        touched,
                        handleChange,
                        handleBlur,
                        handleSubmit,
                        isSubmitting,
                        /* and other goodies */
                        }) => (
                        <form onSubmit={handleSubmit}>
                            <Grid container spacing={2}>
                                <Grid item xs={12} sx={{ textAlign: 'center' }}>
                                    <Typography id="modal-modal-title" variant="subtitle1" fontWeight="700">
                                        Ubah Rekening
                                    </Typography>
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        id="outlined-multiline-flexible"
                                        required
                                        fullWidth
                                        label="Nama Bank"
                                        onChange={handleChange}
                                        name="bank"
                                        defaultValue={valToEdit.bank}
                                    />
                                    <Typography id="modal-modal-title" color="red" variant="subtitle2" component="span" sx={{ padding: '5px'}}>
                                        {errors.bank && touched.bank && errors.bank}
                                    </Typography>
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        id="outlined-multiline-flexible"
                                        required
                                        fullWidth
                                        label="Nama Pemilik"
                                        onChange={handleChange}
                                        name="namapemilik"
                                        defaultValue={valToEdit.namapemilik}
                                    />
                                    <Typography id="modal-modal-title" color="red" variant="subtitle2" component="span" sx={{ padding: '5px'}}>
                                        {errors.namapemilik && touched.namapemilik && errors.namapemilik}
                                    </Typography>
                                </Grid>
                                <Grid item xs={12}>
                                    <TextField
                                        id="outlined-multiline-flexible"
                                        required
                                        fullWidth
                                        label="Nomor Rekening"
                                        onChange={handleChange}
                                        // inputProps={{ inputMode: 'numeric', pattern: '[0-9]*', type: 'number' }}
                                        name="rekening"
                                        defaultValue={valToEdit.rekening}
                                    />
                                    <Typography id="modal-modal-title" color="red" variant="subtitle2" component="span" sx={{ padding: '5px'}}>
                                        {errors.rekening && touched.rekening && errors.rekening}
                                    </Typography>
                                </Grid>
                                <Grid item xs={12} sx={{ textAlign: 'right', padding: '10px 0px' }}>
                                    <Button variant="contained" type="submit" disabled={isSubmitting}>Update</Button>
                                </Grid>
                            </Grid>
                        </form>
                        )}
                    </Formik>
                </Box>
            </Modal>
            <Grid container spacing={2}>
                <Grid item xs={12} sx={{ margin: '10px 14px'}}>
                    <Typography variant="h5" fontWeight="700">Rekeningku</Typography>
                </Grid>
                <Grid item xs={12} sx={{ margin: '10px 14px'}}>
                    <Fab color="primary" aria-label="add" onClick={handleOpen}>
                        <AddIcon />
                    </Fab>
                </Grid>
                <Grid item xs={12} my={1}>
                    <TableContainer component={Paper} sx={{ maxHeight: {xs: '70vh', sm: 740, md: 800} }}>
                        <Table stickyHeader aria-label="sticky table" sx={{ minWidth: 500 }}>
                            <TableHead>
                                <TableRow>
                                    <TableCell><Typography variant="subtitle2" fontWeight="700">No</Typography></TableCell>
                                    <TableCell><Typography variant="subtitle2" fontWeight="700">Nama Bank</Typography></TableCell>
                                    <TableCell><Typography variant="subtitle2" fontWeight="700">Nama Pemilik</Typography></TableCell>
                                    <TableCell><Typography variant="subtitle2" fontWeight="700">No Rekening</Typography></TableCell>
                                    <TableCell><Typography variant="subtitle2" fontWeight="700">Opsi</Typography></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                            {data.map((row) => (
                                <TableRow
                                    key={row.idrek}
                                    sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
                                >
                                    <TableCell>{row.no}</TableCell>
                                    <TableCell>{row.bank}</TableCell>
                                    <TableCell>{row.namapemilik}</TableCell>
                                    <TableCell align="right">{row.rekening}</TableCell>
                                    <TableCell>
                                        <EditIcon onClick={() => handleOpenEdit(row) } color="primary" />
                                        <DeleteIcon onClick={() => handleDeleteDialog(row.idrek) } color="primary" />
                                    </TableCell>
                                </TableRow>
                            ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </Grid>
            </Grid>
        </Container>
    )
}

export default Rekeningku
