const verifyToken = (serviceToken) => {
  if (!serviceToken) {
      return false;
  }
  const decoded = jwtDecode(serviceToken);
  /**
   * Property 'exp' does not exist on type '<T = unknown>(token: string, options?: JwtDecodeOptions | undefined) => T'.
   */
  return decoded.exp > Date.now() / 1000;
};

const ReadyStock = ({ Cart, UpdatedCart }) => {

    const [cartState, setCartState] = useState([]);
    const [jmlState, setJmlState] = useState(0);
    const [totalState, setTotalState] = useState(0);
    
    const [isCheckedOut, setCheckedOut] = useState(false);
    const [productsData, setProductsData] = useState([]);
    const [token, setToken] = useState(
      JSON.parse(localStorage.getItem('token')) !== null ? 
          JSON.parse(localStorage.getItem('token')).token :
          null
    );

    const [page, setPage] = useState({ value: 1 });
    const [pageInfo, setPageInfo] = useState(null);
    const [pageSize, setPageSize] = useState({ value: 24 });

    const [pageForInfo, setPageForInfo] = useState({ value: 1 });
    const [pageInfoInfo, setPageInfoInfo] = useState(null);
    const [pageInfoSize, setPageInfoSize] = useState({ value: 24 });

    const getProducts = async (page, search = null) => {
      try {
        const products = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/readystok/list`, {
          headers: {
            Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
          },
          params: {
              namaproduk: search,
              page: page.value,
              perPage: pageSize.value
          }
        });
        let number = 0;
        setProductsData(products.data.result.data.map((v) => {
          number+=1;
          return { ...v, no: number };
        }));
        const pageInfoRes = Object.keys(products.data.result)
          .filter((key) => {
              if (key !== 'data') return true;
              return false;
          })
          .reduce((cur, key) => Object.assign(cur, { [key]: products.data.result[key] }), {});
        setPageInfo(pageInfoRes);
      } catch (err) {
        console.log(err);
      }
    }

    useEffect(() => {
      const getCart = async () => {
        try {
          const cartData = await axios.get(`${process.env.REACT_APP_API_URL}/api/dashboard/cart/list`, {
            headers: {
              Authorization: `Bearer ${JSON.parse(localStorage.getItem('token')).token}`
            }
          });
          setCartState(cartData.data.result);
        } catch (err) {
          console.log(err);
        }
      };
      getCart();
      window.localStorage.removeItem('curPage');
      window.localStorage.removeItem('searchReadyStock');
      getProducts(page);
      setInterval(() => {
        getProducts(
          { value: localStorage.getItem('curPage') ?? page.value },
          localStorage.getItem('searchReadyStock') ?? null
        )
      }, 10000);
    },[]);

    return (
        <div>
            <Navbar
              cartState={cartState}
              UpdatedCartState={setCartState}
              jmlState={jmlState}
              totalState={totalState}
              UpdatedTotalState={setTotalState}
              UpdatedJmlState={setJmlState}
              UpdatedProductState={setProductsData}
              UpdatedPageInfo={setPageInfo}
              UpdatedPageSize={setPageSize}
              UpdatedPage={setPage}
              Page={page}
              PageInfo={pageInfo}
              PageSize={pageSize}
            />
            {!isCheckedOut ? (
                <Products
                  Cart={Cart}
                  UpdatedCartState={setCartState}
                  UpdatedTotalState={setTotalState}
                  UpdatedJmlState={setJmlState}
                  ProductsData={productsData}
                  UpdatedProductsData={setProductsData}
                  UpdatedPage={setPage}
                  UpdatedPageInfo={setPageInfo}
                  UpdatedPageSize={setPageSize}
                  Page={page}
                  PageInfo={pageInfo}
                  PageSize={pageSize}
                />
            ) : (
                <ReadyStockCheckingOut />
            )}
            <FooterNav />
        </div>
    )
}

export default ReadyStock
